// Language detection map
const LANG_MAP = {
  "en":"en","en-US":"en","en-GB":"en","en-AU":"en",
  "ar":"ar","ar-EG":"ar","ar-SA":"ar",
  "ru":"ru","ru-RU":"ru",
  "de":"de","de-DE":"de","de-AT":"de","de-CH":"de",
  "fr":"fr","fr-FR":"fr","fr-BE":"fr","fr-CA":"fr",
  "it":"it","it-IT":"it",
  "es":"es","es-ES":"es","es-MX":"es","es-AR":"es",
  "pl":"pl","pl-PL":"pl",
  "tr":"tr","tr-TR":"tr",
  "zh":"zh","zh-CN":"zh","zh-TW":"zh","zh-HK":"zh",
  "uk":"uk","uk-UA":"uk",
  "ro":"ro","ro-RO":"ro",
  "cs":"cs","cs-CZ":"cs",
  "nl":"nl","nl-NL":"nl","nl-BE":"nl",
  "sv":"sv","sv-SE":"sv",
  "pt":"pt","pt-BR":"pt","pt-PT":"pt",
  "ja":"ja","ja-JP":"ja",
  "ko":"ko","ko-KR":"ko",
  "hu":"hu","hu-HU":"hu",
  "fi":"fi","fi-FI":"fi"
};

function detectLanguage() {
  const path = window.location.pathname;
  const pathParts = path.split('/');
  for (const part of pathParts) {
    if (part && TRANSLATIONS[part]) {
      localStorage.setItem('aqw_lang', part);
      return part;
    }
  }
  const params = new URLSearchParams(window.location.search);
  const urlLang = params.get('lang');
  if (urlLang && TRANSLATIONS[urlLang]) {
    localStorage.setItem('aqw_lang', urlLang);
    return urlLang;
  }
  const stored = localStorage.getItem('aqw_lang');
  if (stored && TRANSLATIONS[stored]) return stored;
  const browserLangs = navigator.languages || [navigator.language || 'en'];
  for (const l of browserLangs) {
    const code = LANG_MAP[l] || LANG_MAP[l.split('-')[0]];
    if (code && TRANSLATIONS[code]) return code;
  }
  return 'en';
}

window.AQW_LANG = detectLanguage();
window.AQW_T = TRANSLATIONS[window.AQW_LANG];


